sp_widget.client_script:
api.controller = function ($scope, $rootScope) {
  var c = this;

  c.loading = false;

  // Listen for visit updates to refresh guest list
  $scope.$on("sp.visit.updated", function () {
    c.refresh();
  });

  c.refresh = function () {
    c.data.message = "";
    c.data.success = false;
    c.data.error = false;
    c.server.get({ visit_sys_id: c.data.visitSysId }).then(function (r) {
      c.data = r.data;
    });
  };

  c.guestAction = function (action, guest) {
    c.loading = true;
    c.data.message = "";
    c.data.success = false;
    c.data.error = false;
    c.server.get({
      guest_action: action,
      guest_sys_id: guest.sys_id,
      visit_sys_id: c.data.visitSysId
    }).then(function (r) {
      c.data = r.data;
      c.loading = false;
      // Notify visit detail to refresh too
      $rootScope.$broadcast("sp.guest.updated", { visit_sys_id: c.data.visitSysId });
    }, function () {
      c.loading = false;
    });
  };

  c.canCheckInGuest = function (guest) {
    return guest && guest.status === "pending";
  };

  c.canCheckOutGuest = function (guest) {
    return guest && guest.status === "checked_in";
  };

  c.getStatusClass = function (status) {
    var map = {
      pending: "label-warning",
      checked_in: "label-success",
      checked_out: "label-default"
    };
    return map[status] || "label-default";
  };

  c.getStatusLabel = function (status) {
    var map = {
      pending: "Pending",
      checked_in: "Checked In",
      checked_out: "Checked Out"
    };
    return map[status] || status;
  };
};

sp_widget.css:
/* Card */
.sp-card {
  display: flex;
  flex-direction: column;
  width: 100%;
  border: 1px solid $border-tertiary;
  border-radius: $border-radius-large;
  box-shadow: 0 1px 4px rgba($text-color, 0.07);
  background: $background-primary;
  overflow: hidden;
  margin-bottom: 0;
}
.sp-card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 24px;
  background: $background-primary;
  border-bottom: 1px solid $border-tertiary;
  min-height: 52px;
}
.sp-card-title {
  font-size: $font-size-large;
  font-weight: 600;
  color: $text-color;
  margin: 0;
}
.sp-card-icon { margin-right: 8px; color: $brand-primary; font-size: 16px; }
.sp-card-body-flush { padding: 0; flex: 1 1 auto; overflow-x: auto; }
.sp-card-body { padding: 24px; flex: 1 1 auto; }

/* Alert */
.sp-alert {
  margin: 0 0 16px 0;
  border-radius: $border-radius-large;
  font-size: $font-size-small;
}
.sp-alert .glyphicon { margin-right: 6px; }

/* Table */
.sp-th {
  font-size: 12px;
  font-weight: 600;
  color: $text-muted;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 12px 16px;
  border-bottom: 2px solid $border-tertiary;
  background: $background-secondary;
  white-space: nowrap;
}
.sp-td {
  font-size: $font-size-small;
  padding: 12px 16px;
  color: $text-color;
  border-bottom: 1px solid $border-tertiary;
  vertical-align: middle;
}

/* Action cell */
.sp-action-cell {
  white-space: nowrap;
}
.sp-btn-action {
  font-size: 11px;
  padding: 3px 10px;
  border-radius: $border-radius-base;
}
.sp-btn-action .glyphicon { margin-right: 3px; font-size: 11px; }
.sp-done-label {
  font-size: 11px;
  font-style: italic;
}
.sp-done-label .glyphicon { margin-right: 3px; }

/* Empty State */
.sp-empty-state { padding: 48px 24px; }
.sp-empty-icon {
  font-size: 48px;
  margin-bottom: 16px;
  display: block;
  opacity: 0.35;
  color: $text-muted;
}
.sp-empty-title {
  font-size: $font-size-large;
  font-weight: 600;
  color: $text-color;
  margin-bottom: 8px;
}

sp_widget.script:
(function () {
  data.guests = [];
  data.visitSysId = "";
  data.message = "";
  data.success = false;
  data.error = false;

  try {
    var visitSysId = "";
    if (input && input.visit_sys_id) {
      visitSysId = input.visit_sys_id;
    } else {
      visitSysId = $sp.getParameter("sys_id");
    }
    data.visitSysId = visitSysId;

    // Handle guest actions (individual check-in/check-out)
    if (input && input.guest_action && input.guest_sys_id) {
      var guestGr = new GlideRecord("x_1085196_visita_0_guest");
      if (guestGr.get(input.guest_sys_id)) {
        var currentStatus = guestGr.getValue("status");
        if (input.guest_action === "check_in" && currentStatus === "pending") {
          guestGr.setValue("status", "checked_in");
          guestGr.setValue("check_in_time", new GlideDateTime().getValue());
          guestGr.update();
          data.success = true;
          data.message = guestGr.getValue("first_name") + " " + guestGr.getValue("last_name") + " checked in.";
        } else if (input.guest_action === "check_out" && currentStatus === "checked_in") {
          guestGr.setValue("status", "checked_out");
          guestGr.setValue("check_out_time", new GlideDateTime().getValue());
          guestGr.update();
          data.success = true;
          data.message = guestGr.getValue("first_name") + " " + guestGr.getValue("last_name") + " checked out.";
        } else {
          data.error = true;
          data.message = "Action not allowed for the current guest status.";
        }
      }
    }

    // Load guest list
    if (visitSysId) {
      var gr = new GlideRecord("x_1085196_visita_0_guest");
      gr.addQuery("visit", visitSysId);
      gr.orderBy("last_name");
      gr.setLimit(50);
      gr.query();

      while (gr.next()) {
        data.guests.push({
          sys_id: gr.getUniqueValue(),
          first_name: gr.getValue("first_name"),
          last_name: gr.getValue("last_name"),
          email: gr.getValue("email"),
          phone: gr.getValue("phone"),
          company: gr.getValue("company"),
          id_type: gr.getDisplayValue("id_type") + "",
          id_number: gr.getValue("id_number"),
          status: gr.getValue("status"),
          check_in_time: gr.getDisplayValue("check_in_time") + "",
          check_out_time: gr.getDisplayValue("check_out_time") + ""
        });
      }
    }
  } catch (e) {
    gs.error("Guest List error: " + e.message);
    data.error = true;
    data.message = "An error occurred loading guests.";
  }
})();
